const d = $input.first().json || {};
const al = d.alerts || {};
const hasChannel = !!((al.email && al.email.to) || (al.whatsapp && al.whatsapp.phone && al.whatsapp.apikey));
if (!hasChannel || !(al.enabled === true)) return [];
const top = (d.top || []).map((l) => '- ' + l.title + ' (' + l.source + (l.fit_score != null ? ', fit ' + l.fit_score : '') + ')').join('
');
const lines = [
  'New leads in 24 h: ' + d.new_leads + ' | Strong matches waiting: ' + d.strong + ' | Trade matches: ' + d.trade_matches,
  'Drafts to review: ' + d.drafts + ' | Replies waiting: ' + d.replies + ' | Tasks due: ' + d.tasks_due + ' | Open deals: ' + d.open_deals,
];
if (top) lines.push('Best new leads:', top);
lines.push('http://localhost:3000');
return [{ json: { payload: { subject: 'Lead Radar daily summary', text: lines.join('
') } } }];
